mapper.select:
SELECT st.seat_seq AS seatSeq, st.schedule_seq AS scheduleSeq, st.car_no AS carNo, st.seat_no AS seatNo, st.seat_grade AS seatGrade, 'CONFIRMED' AS status, st.version FROM seat st WHERE st.schedule_seq = #{scheduleSeq}
AND st.car_no = #{carNo}
ORDER BY st.car_no ASC, CAST(NULLIF(REGEXP_REPLACE(st.seat_no, '\D', '', 'g'), '') AS INTEGER) ASC, REGEXP_REPLACE(st.seat_no, '\d', '', 'g') ASC
